function Icon({name,size=22}){const I=iconMap[name]||Flower2;return <span className="icon"><I size={size} strokeWidth={1.7}/></span>}
function Mark({className=''}){return <img className={'brand-mark '+className} src={A+'aram-logo.png'} alt=""/>}
function Logo(){return <a className="logo" href="#home" aria-label="ARAM ERP home"><Mark/><span>ARAM ERP<small>One Platform. Every Faith.</small></span></a>}
function Eyebrow({children}){return <div className="eyebrow">{children}<span/></div>}
const orbit=[['finance','Finance & Accounts','one'],['people','People','two'],['operations','Operations','three'],['reports','Reports & Analytics','four'],['sevas','Sevas & Services','five'],['donations','Donations','six']];
const petalPath=(wl,wr,tip,lean)=>`M0,-96C-50,-100 ${-wl+6},-122 ${-wl},-170C${-wl-6},-222 ${-80+lean},-262 ${-40+lean},-288C${-22+lean},-299 ${-8+lean},-308 ${lean},${-tip}C${8+lean},-308 ${22+lean},-299 ${40+lean},-288C${80+lean},-262 ${wr+6},-222 ${wr},-170C${wr-6},-122 50,-100 0,-96Z`;
const PETALS=[[98,98,326,0],[97,99,324,1],[99,97,327,-1],[98,98,325,.5],[99,98,326,-.5],[97,99,325,1]].map(([wl,wr,tip,lean])=>petalPath(wl,wr,tip,lean));
const INNER=petalPath(98,98,326,0);
const lotusNotes={finance:'Ledgers, receipts & audit-ready books',people:'Staff, volunteers & payroll',operations:'Assets, inventory & daily tasks',reports:'Live dashboards & compliance',sevas:'Bookings, schedules & offerings',donations:'Donor care, receipts & 80G'};
const seeded=n=>{let x=Math.sin(n*9301+49297)*233280;return x-Math.floor(x)};
const sparkles=Array.from({length:34},(_,i)=>{const a=seeded(i+1)*Math.PI*2,r=150+seeded(i+41)*200;return{x:+(Math.cos(a)*r).toFixed(1),y:+(Math.sin(a)*r).toFixed(1),r:+(.7+seeded(i+83)*.9).toFixed(2),d:+(6+seeded(i+127)*6).toFixed(2),o:+(-seeded(i+171)*12).toFixed(2)}});
const VB=360,OFF=[30,90,150,210,270,330];
const face='translate(0,-96) scale(.94,.95) translate(0,96)';
function Lotus(){const[on,setOn]=useState(-1);const pos=useRef(null);const vb=`${-VB} ${-VB} ${VB*2} ${VB*2}`;
const probe=()=>{const p=pos.current;if(!p)return;const el=document.elementFromPoint(p.x,p.y);const g=el&&el.closest?el.closest('.lotus-petal'):null;setOn(g?+g.dataset.k:-1)};
useEffect(()=>{const id=setInterval(probe,120);return()=>clearInterval(id)},[]);
const track=e=>{pos.current={x:e.clientX,y:e.clientY};probe()};
return <div className="lotus" onPointerMove={track} onPointerDown={track} onPointerLeave={()=>{pos.current=null;setOn(-1)}} role="img" aria-label="ARAM ERP at the centre of six functions: Finance & Accounts, People, Operations, Reports & Analytics, Sevas & Services and Donations">
<svg className="lotus-art lotus-under" viewBox={vb} aria-hidden="true">
<defs><filter id="lg-blur" x="-50%" y="-300%" width="200%" height="700%"><feGaussianBlur stdDeviation="14"/></filter>
<radialGradient id="lg-halo-bg"><stop offset="0" stopColor="#f8e3da" stopOpacity=".85"/><stop offset=".55" stopColor="#fbeee8" stopOpacity=".55"/><stop offset="1" stopColor="#fff" stopOpacity="0"/></radialGradient>
<radialGradient id="lg-gold"><stop offset="0" stopColor="#fffbea"/><stop offset=".35" stopColor="#ffe08a"/><stop offset=".7" stopColor="#f0b93a"/><stop offset="1" stopColor="#c98f1e"/></radialGradient>
<filter id="lg-shine" x="-300%" y="-300%" width="700%" height="700%"><feGaussianBlur in="SourceGraphic" stdDeviation="2.2" result="halo"/><feColorMatrix in="halo" type="matrix" values="1 0 0 0 .1  0 .85 0 0 .05  0 0 .4 0 0  0 0 0 .9 0" result="warm"/><feMerge><feMergeNode in="warm"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>
<circle r="360" fill="url(#lg-halo-bg)"/>
<g className="lotus-orbit" fill="none"><circle r="352" stroke="#efdcd4" strokeWidth=".8"/><circle r="312" stroke="#e8d0c7" strokeWidth=".8" strokeDasharray="1.5 6"/><circle r="262" stroke="#eed8cf" strokeWidth=".8"/>{Array.from({length:12},(_,i)=><circle key={i} transform={`rotate(${i*30+15})`} cy="-312" r={i%2?1.4:2.2} fill="url(#lg-gold)" stroke="none"/>)}</g>
<g className="lotus-gold" filter="url(#lg-shine)">{sparkles.map((p,i)=>i%3===0?<path key={i} className="star" d={`M0,${-p.r*4}Q${p.r*.35},${-p.r*.35} ${p.r*4},0Q${p.r*.35},${p.r*.35} 0,${p.r*4}Q${-p.r*.35},${p.r*.35} ${-p.r*4},0Q${-p.r*.35},${-p.r*.35} 0,${-p.r*4}Z`} transform={`translate(${p.x},${p.y})`} style={{animationDuration:(p.d*.6).toFixed(3)+'s',animationDelay:p.o+'s'}}/>:<circle key={i} cx={p.x} cy={p.y} r={p.r} fill="url(#lg-gold)" style={{animationDuration:(p.d*.55).toFixed(3)+'s',animationDelay:p.o+'s'}}/>)}{[[-250,-238],[292,-96],[236,232],[-300,128],[40,-338],[-120,318]].map(([x,y],i)=><path key={i} className="glint" d="M0,-6Q.5,-.5 6,0Q.5,.5 0,6Q-.5,.5 -6,0Q-.5,-.5 0,-6Z" transform={`translate(${x},${y})`} style={{animationDelay:(-i*2.3).toFixed(1)+'s'}}/>)}</g>
<ellipse className="lotus-shadow" cx="0" cy="340" rx="185" ry="12" fill="#5a3432" filter="url(#lg-blur)"/>
</svg>
<div className="lotus-spin">
<svg className="lotus-art" viewBox={vb} aria-hidden="true" shapeRendering="geometricPrecision">
<defs>
<linearGradient id="lg-rim" gradientUnits="userSpaceOnUse" x1="0" y1="-96" x2="0" y2="-326"><stop offset="0" stopColor="#eec3c4"/><stop offset=".5" stopColor="#f6d8d8"/><stop offset="1" stopColor="#f0c7ca"/></linearGradient>
<radialGradient id="lg-face" gradientUnits="userSpaceOnUse" cx="0" cy="-236" r="150" fx="0" fy="-250"><stop offset="0" stopColor="#fffefd"/><stop offset=".45" stopColor="#fffaf8"/><stop offset=".75" stopColor="#fcefed"/><stop offset="1" stopColor="#f5d9d8"/></radialGradient>
<linearGradient id="lg-inner-p" gradientUnits="userSpaceOnUse" x1="0" y1="-96" x2="0" y2="-326"><stop offset="0" stopColor="#efc6c7"/><stop offset=".6" stopColor="#f8e0df"/><stop offset="1" stopColor="#f3d0d2"/></linearGradient>
<linearGradient id="lg-edge" gradientUnits="userSpaceOnUse" x1="0" y1="-96" x2="0" y2="-326"><stop offset="0" stopColor="#c47c84" stopOpacity=".55"/><stop offset=".35" stopColor="#ab2d3c"/><stop offset="1" stopColor="#991a2a"/></linearGradient>
<radialGradient id="lg-bloom" gradientUnits="userSpaceOnUse" cx="0" cy="-96" r="234"><stop offset="0" stopColor="#e8a6ae" stopOpacity=".8"/><stop offset=".4" stopColor="#f2c6ca" stopOpacity=".6"/><stop offset=".75" stopColor="#f9dfe0" stopOpacity=".4"/><stop offset="1" stopColor="#fff" stopOpacity=".15"/></radialGradient>
<linearGradient id="lg-sheen" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stopColor="#fff" stopOpacity="0"/><stop offset=".5" stopColor="#fff" stopOpacity=".7"/><stop offset="1" stopColor="#fff" stopOpacity="0"/></linearGradient>
{PETALS.map((d,k)=><clipPath key={k} id={`lg-clip-${k}`}><path d={d}/></clipPath>)}
</defs>
{orbit.map(([,t],k)=><g key={t} transform={`rotate(${k*60})`}><g className={'lotus-petal'+(on===k?' on':'')} data-k={k} style={{'--i':k}}><path className="petal-shadow" d={PETALS[k]} transform="translate(0,-96) scale(1.02) translate(0,99)"/><path className="petal-rim" d={PETALS[k]}/><g clipPath={`url(#lg-clip-${k})`}><path className="petal-face" d={PETALS[k]} transform={face}/><path className="petal-fold" d={PETALS[k]} transform={face}/><circle className="petal-bloom" cx="0" cy="-96" r="234" fill="url(#lg-bloom)"/><rect className="petal-sheen" x="-110" y="-160" width="220" height="56" fill="url(#lg-sheen)"/></g><path className="petal-edge" d={PETALS[k]}/></g></g>)}
<g className="lotus-inner-ring">{[0,60,120,180,240,300].map(a=><g key={a} className="inner-soft" transform={`rotate(${a}) scale(.36,.5)`}><path className="inner-rim" d={INNER}/></g>)}{OFF.map(a=><g key={a} transform={`rotate(${a}) scale(.44,.6)`}><path className="inner-rim" d={INNER}/><path className="inner-face" d={INNER} transform="translate(0,-96) scale(.86,.88) translate(0,96)"/></g>)}</g>
</svg>
{orbit.map(([i,t],k)=>{const a=k*Math.PI/3,r=208,f=50/VB;return <div key={t} className={'lotus-label'+(on===k?' on':'')} style={{left:(50+Math.sin(a)*r*f).toFixed(4)+'%',top:(50-Math.cos(a)*r*f).toFixed(4)+'%'}} onFocus={()=>setOn(k)} onBlur={()=>setOn(-1)} tabIndex={0}><div className="lotus-label-in"><LotusIcon name={i}/><h3>{t.replace(' & ',' & ')}</h3><p>{lotusNotes[i]}</p></div></div>})}
</div>
<svg className="lotus-art lotus-top" viewBox={vb} aria-hidden="true" shapeRendering="geometricPrecision">
<defs>
<radialGradient id="lg-disc" cx=".5" cy=".42" r=".62"><stop offset="0" stopColor="#fff"/><stop offset=".6" stopColor="#fffcfa"/><stop offset=".86" stopColor="#fcefe9"/><stop offset="1" stopColor="#f7dccf"/></radialGradient>
<linearGradient id="lg-ring" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stopColor="#f6e4bb"/><stop offset=".35" stopColor="#d2a960"/><stop offset=".65" stopColor="#f3dca6"/><stop offset="1" stopColor="#bf9350"/></linearGradient>
<filter id="lg-disc-shadow" x="-40%" y="-40%" width="180%" height="180%"><feDropShadow dx="0" dy="6" stdDeviation="11" floodColor="#7a4a44" floodOpacity=".18"/></filter>
</defs>
<circle r="102" fill="url(#lg-disc)" filter="url(#lg-disc-shadow)"/>
<circle r="102" fill="none" stroke="url(#lg-ring)" strokeWidth="3.4"/>
<circle r="98.6" fill="none" stroke="#fff" strokeOpacity=".8" strokeWidth=".8"/>
</svg>
<div className="lotus-core"><Mark/><strong>ARAM ERP</strong><span>One Platform</span></div>
</div>}
function LotusLeaf(props){return <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" {...props}><path d="M12 3.5C9.6 6.4 9.6 10.6 12 14.5C14.4 10.6 14.4 6.4 12 3.5Z"/><path d="M12 14.5C8.6 14.2 6.1 11.8 5.6 8C8.6 8.4 10.8 10.2 12 14.5"/><path d="M12 14.5C15.4 14.2 17.9 11.8 18.4 8C15.4 8.4 13.2 10.2 12 14.5"/><path d="M4.5 13.5C6.3 17 8.9 18.6 12 18.6S17.7 17 19.5 13.5"/><path d="M12 18.6V21"/></svg>}
const lotusIcons={finance:Mail,people:UsersRound,operations:Share2,reports:ChartNoAxesCombined,sevas:LotusLeaf,donations:HeartHandshake};
function LotusIcon({name}){const I=lotusIcons[name]||Flower2;return <I className="lotus-icon" strokeWidth={1.7} aria-hidden="true"/>}
function Header(){const[open,setOpen]=useState(false);const[drop,setDrop]=useState(-1);const toggle=i=>e=>{if(window.matchMedia('(max-width:720px)').matches){e.preventDefault();setDrop(drop===i?-1:i)}};const close=()=>{setOpen(false);setDrop(-1)};return <header><div className="nav-wrap"><Logo/><button className="menu" onClick={()=>{setOpen(!open);setDrop(-1)}} aria-label="Toggle menu" aria-expanded={open}>{open?<X/>:<Menu/>}</button><nav className={open?'open':''}><div className={'nav-drop'+(drop===0?' show':'')}><a href="#solutions" onClick={toggle(0)} aria-expanded={drop===0}>Solutions <ChevronDown size={13}/></a><div className="drop-panel"><a href="/trusts" target="_blank" rel="noopener" onClick={close}>Trust</a><a href="/mms" target="_blank" rel="noopener" onClick={close}>Matha</a><a href="/temple" target="_blank" rel="noopener" onClick={close}>Temple</a></div></div><a href="#features" onClick={close}>Features</a><a href="#process" onClick={close}>How we work</a><a href="#why-aram" onClick={close}>Why ARAM</a><a href="#about" onClick={close}>About</a><a href="#contact" onClick={close}>Contact</a><a className="button nav-cta" href="#contact" onClick={close}>Get Started <ArrowUpRight size={15}/></a></nav></div></header>}
function Hero(){return <section id="home" className="hero"><div className="container hero-grid"><div className="hero-copy"><Eyebrow>Faith · Community · Impact</Eyebrow><h1>Simplifying<br/>Operations for<br/>Mutts, Temples<br/>and Trusts</h1><p>A unified ERP platform to manage donations, finances, assets, people and daily operations — with clarity, security and ease.</p><div className="actions"><a className="button" href="#contact">Get Started <ArrowUpRight size={16}/></a><a className="watch" href="#platform"><i><Play size={12} fill="currentColor"/></i> Explore platform</a></div></div><Lotus/></div></section>}
const finance=[['income','Income & Expense Tracking','Track donations, expenses and transactions.'],['budget','Budget Management','Plan and monitor fund allocation.'],['reports','Automated Reports','Generate decision-ready financial reports.'],['bank','Bank Reconciliation','Match and verify transactions with confidence.'],['accounts','Multi-Account Support','Manage multiple accounts and designated funds.'],['audit','Audit Trail','Maintain a complete, secure transaction history.']];
function Features(){const featureIcons=[HandCoins,ChartColumnIncreasing,ChartNoAxesCombined,Landmark,WalletCards,FileCheck2];return <section id="features" className="section finance"><div className="container split"><div className="section-copy sticky-copy"><Eyebrow>Key Features</Eyebrow><h2>Financial Clarity<br/>for Greater Impact</h2><p>Enterprise-grade financial controls, designed around the real operating needs of institutions.</p><a className="text-link" href="#platform">Explore the platform <ArrowUpRight size={15}/></a></div><div className="feature-grid">{finance.map(([i,t,d],n)=>{const FeatureIcon=featureIcons[n];return <article key={t}><span className="feature-no">0{n+1}</span><span className="feature-icon"><FeatureIcon size={25} strokeWidth={1.8}/></span><div><h3>{t}</h3><p>{d}</p></div></article>})}</div></div></section>}
const dashboardTabs=[['Dashboard','A complete overview of collections, sevas and what’s coming up.'],['Operations','Sevas, schedules and daily activity—together in one clear view.'],['Finance','Devotees, donations and financial records, easy to review.']];
const operationsRows=[['Anndanam','₹300','—','Sankalpam · Annadhanam','17 Sept 2026'],['Daily Archana','₹10','1','Sankalpam · Archana','10 Sept 2026'],['Ananthapadmanaba Vratham','₹1,700','2','Sankalpam · Archana · Pooja','6 Sept 2026'],['Ghee Deepa','₹50','—','Sankalpam','2 Sept 2026'],['Sarva Seva (3 Days)','₹3,000','—','Sankalpam · Abhishekam','30 Aug 2026']];
const financeRows=[['D547','R. Supriya','16 Sept 2026','₹14,500'],['D544','Nila','16 Sept 2026','₹6,501'],['D1227','Sathyanarayan','6 Sept 2026','₹120'],['D545','R. Ramesh','6 Sept 2026','₹10,000'],['D754','V. Shankar','17 Aug 2026','₹13,000']];
function OperationsPreview(){return <div className="operations-preview" role="img" aria-label="Operations dashboard preview with seva bookings, rates, rituals and last booked dates"><div className="operations-title"><div><span className="preview-kicker">OPERATIONS · SEVAS</span><strong>Seva management</strong><small>Bookings, rituals and services at a glance</small></div><span className="preview-action">＋ Add new seva</span></div><div className="ops-tabs"><b>Sevas</b><span>Donations</span><span>Projects</span><span>Panchangam</span><span>General Ledger</span></div><div className="ops-toolbar"><span>Search seva name, deity, ritual...</span><span>All Status　⌄</span><span>Columns</span></div><div className="ops-table"><div className="ops-row ops-labels"><span>SEVA NAME</span><span>RATE (₹)</span><span>TP</span><span>RITUALS</span><span>LAST BOOKED</span></div>{operationsRows.map(row=><div className="ops-row" key={row[0]}>{row.map((cell,i)=><span key={i}>{cell}</span>)}</div>)}</div></div>}
function FinancePreview(){return <div className="finance-preview" role="img" aria-label="Finance dashboard preview showing devotee donation records"><div className="finance-preview-head"><div><span className="preview-kicker">PEOPLE · DEVOTEES</span><strong>Devotees</strong><small>746 devotees · click a row for details</small></div><span className="preview-action">＋ Add devotee</span></div><div className="preview-tools"><span>Search devotees</span><span>All roles　⌄</span><span>Columns</span></div><div className="preview-table"><div className="preview-row preview-labels"><span>DEVOTEE ID</span><span>DEVOTEE</span><span>LAST DONATION</span><span>TOTAL DONATED</span></div>{financeRows.map(row=><div className="preview-row" key={row[0]}>{row.map((cell,i)=><span key={i}>{cell}</span>)}</div>)}</div><div className="preview-mobile-note">Finance &amp; devotee records</div></div>}
function Platform(){const[tab,setTab]=useState(0);return <section id="platform" className="section platform"><div className="container"><div className="platform-head"><div><Eyebrow>The ARAM Platform</Eyebrow><h2>One clear view.<br/>Every moving part.</h2></div><p>{dashboardTabs[tab][1]}</p></div><div className="dash-tabs">{dashboardTabs.map(([t],i)=><button className={tab===i?'active':''} onClick={()=>setTab(i)} key={t} aria-pressed={tab===i}><span>0{i+1}</span>{t}</button>)}</div><div className="dashboard-shell"><div className="browser-bar"><i/><i/><i/><span>app.aramerp.com / {dashboardTabs[tab][0].toLowerCase()}</span></div>{tab===0?<img src={A+'aram-dashboard.png'} alt="ARAM dashboard overview showing daily collections, sevas and upcoming events"/>:tab===1?<OperationsPreview/>:<FinancePreview/>}<div className="dash-callout"><Check size={15}/><span>{tab===0?'Live institutional overview':tab===1?'Sevas and daily operations':'Financial records at a glance'}</span></div></div></div></section>}
const solutions=[['mutt','Mathas','Manage daily operations, donations and sevas.','/mms'],['temple','Temples','Handle rituals, finances, assets and administration.','/temple'],['trust','Trusts','Track funds, projects, people and compliance.','/trusts']];
function Solutions(){return <section id="solutions" className="section solutions"><div className="container"><div className="section-heading"><div><Eyebrow>Our Solutions</Eyebrow><h2>Built for Every Institution</h2></div><p>Purpose-built products with the flexibility to grow alongside your institution.</p></div><div className="solution-grid">{solutions.map(([v,t,d,href],i)=><article key={t}><div className={'building '+v}/><span className="solution-tag">0{i+1}</span><h3>{t}</h3><p>{d}</p><a href={href} target="_blank" rel="noopener">Explore solution <ArrowUpRight size={15}/></a></article>)}</div></div></section>}
function Impact(){const pillars=[{n:'01',title:'Made for your mission',text:'Purpose-built around how Mutts, Temples and Trusts serve their communities.',icon:Sparkles},{n:'02',title:'One source of truth',text:'Bring finance, people, sevas and projects into one connected workspace.',icon:Network},{n:'03',title:'Confidence in every decision',text:'See clear records, accountable activity and the answers you need—faster.',icon:Eye}];return <section id="why-aram" className="section impact"><div className="container"><div className="impact-heading"><Eyebrow>Why ARAM</Eyebrow><h2>More than software.<br/>A steadier way to serve.</h2><p>Technology that gives your people more time for what matters.</p></div><div className="impact-grid">{pillars.map(({n,title,text,icon:ImpactIcon})=><article className="impact-card" key={n}><div className="impact-card-top"><span>{n}</span><ImpactIcon size={25} strokeWidth={1.7}/></div><h3>{title}</h3><p>{text}</p><span className="impact-accent"/></article>)}</div></div></section>}
function Testimonial(){return <section className="testimonial"><div className="container test-grid testimonial-inner"><div className="testimonial-copy"><Eyebrow>What Our Clients Say</Eyebrow><blockquote>“Daily collections, sevas, and reports are clear at a glance now. What used to take a full day of reconciliation takes minutes.”</blockquote><div className="author"><b>R</b><span>Raghavendra Mutt<small>ARAM ERP client</small></span></div></div><figure><img src={A+'matha-interior.png'} alt="Traditional courtyard with carved pillars and warm morning light"/><figcaption><span>Tradition, supported.</span></figcaption></figure></div></section>}
const steps=[{n:'01',t:'Discover',sub:'Understand your needs',icon:Search,text:'We map your current workflows, stakeholders and priorities so the platform is shaped around the way your institution truly works.'},{n:'02',t:'Configure',sub:'Build your workspace',icon:SlidersHorizontal,text:'Our team configures modules, roles, approvals and reports around your operating model—with no unnecessary complexity.'},{n:'03',t:'Enable',sub:'Train your team',icon:GraduationCap,text:'Role-based training and guided onboarding help every user feel confident from their first day on the platform.'},{n:'04',t:'Grow',sub:'Go live & support',icon:LifeBuoy,text:'We stay with you after launch through responsive support, continuous improvements and a roadmap for what comes next.'}];
function Process(){const[active,setActive]=useState(0);const S=steps[active],I=S.icon;return <section id="process" className="section process"><div className="container"><div className="section-heading"><div><Eyebrow>How We Work</Eyebrow><h2>From complexity<br/>to clarity.</h2></div><p>A proven rollout method that keeps your people informed, involved and ready.</p></div><div className="process-board"><div className="process-tabs">{steps.map((s,i)=><button onClick={()=>setActive(i)} className={active===i?'active':''} key={s.n}><span>{s.n}</span><b>{s.t}</b><small>{s.sub}</small></button>)}</div><div className="process-detail" key={S.n}><span className="detail-icon"><I size={30}/></span><div><small>Step {S.n}</small><h3>{S.t}: {S.sub}</h3><p>{S.text}</p></div><span className="detail-num">{S.n}</span></div></div></div></section>}
function Contact(){const[sent,setSent]=useState(false);return <section id="contact" className="contact section"><div className="container contact-grid"><div><Eyebrow>Get in Touch</Eyebrow><h2>Let's Build a Better<br/>Tomorrow Together</h2><p>Tell us where you are today. We’ll show you what a clearer tomorrow can look like.</p></div><form onSubmit={e=>{e.preventDefault();setSent(true)}}><div className="form-row"><input aria-label="Full Name" placeholder="Full Name" required/><input aria-label="Email Address" type="email" placeholder="Email Address" required/></div><input aria-label="Organization Name" placeholder="Organization Name" required/><select aria-label="Institution Type" defaultValue="" required><option value="" disabled>Select Institution Type</option><option>Matha</option><option>Temple</option><option>Trust</option></select><textarea aria-label="Message" placeholder="Tell us a little about your needs" required minLength="10"/><button className="button">Send Message <ArrowUpRight size={15}/></button>{sent&&<p className="success">Thank you. We’ll be in touch shortly.</p>}</form></div></section>}
function FinalCta(){return <section className="final-cta"><div className="final-overlay"/><div className="container"><Eyebrow>A clearer way forward</Eyebrow><h2>Bring your institution together<br/>with ARAM ERP.</h2><p>One connected platform. More confidence in every decision.</p><a className="button light" href="#contact">Start a conversation <ArrowUpRight size={16}/></a></div></section>}
function Footer(){return <footer><div className="container footer-grid"><div><Logo/><p>Technology that supports institutions<br/>with clarity, care and confidence.</p></div><div><h3>Solutions</h3><a href="/trusts" target="_blank" rel="noopener">Trust</a><a href="/mms" target="_blank" rel="noopener">Matha</a><a href="/temple" target="_blank" rel="noopener">Temple</a></div><div><h3>Platform</h3><a href="#features">Features</a><a href="#process">How we work</a><a href="#why-aram">Why ARAM</a></div><div><h3>Company</h3><a href="#about">About</a><a href="#contact">Contact</a><a href="#">Privacy</a></div></div><div className="container copyright"><span>© {new Date().getFullYear()} ARAM ERP. All rights reserved.</span><span>One Platform. Every Faith.</span></div></footer>}
export default function AramHome(){return <><Header/><main><Hero/><Features/><Platform/><Solutions/><Process/><Impact/><Testimonial/><Contact/><FinalCta/></main><Footer/></>}
